async function audit() {
    console.log('--- Question Bank Audit ---');

    const { data: problems, error } = await supabase
        .from('problems')
        .select('id, title, description, difficulty, tags');

    if (error) {
        console.error('Error fetching problems:', error);
        return;
    }

    console.log(`Total problems: ${problems.length}`);

    // Group by title
    const groups: Record<string, any[]> = {};
    problems.forEach(p => {
        if (!groups[p.title]) groups[p.title] = [];
        groups[p.title].push(p);
    });

    const duplicates = Object.entries(groups).filter(([_, group]) => group.length > 1);

    if (duplicates.length === 0) {
        console.log('No duplicates found by title.');
        return;
    }

    console.log(`\nFound ${duplicates.length} titles with potential duplicates:`);

    duplicates.forEach(([title, group]) => {
        console.log(`\n[${title}] - ${group.length} entries:`);
        group.forEach(p => {
            const descPreview = p.description.slice(0, 50).replace(/\n/g, ' ') + '...';
            console.log(`  - ID: ${p.id} | Desc Length: ${p.description.length} | Difficulty: ${p.difficulty}`);
            console.log(`    Preview: ${descPreview}`);
        });

        // Suggest which one to keep (longest description)
        const sorted = [...group].sort((a, b) => b.description.length - a.description.length);
        console.log(`  -> RECOMMEND KEEPING ID: ${sorted[0].id}`);
        console.log(`  -> RECOMMEND DELETING: ${sorted.slice(1).map(p => p.id).join(', ')}`);
    });
}

audit();

import { createClient } from '@supabase/supabase-js';
import * as dotenv from 'dotenv';
import path from 'path';
import fs from 'fs';

dotenv.config({ path: path.resolve(process.cwd(), '.env.local') });

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY!;
const supabase = createClient(supabaseUrl, supabaseKey);

// Generic algorithm names that are usually too simple for interview problems
const GENERIC_TITLES = new Set([
    "Binary Search", "Linear Search", "Bubble Sort", "Quick Sort", "Merge Sort", "Insertion Sort",
    "Selection Sort", "Heap Sort", "Depth First Search", "Breadth First Search", "Linked List",
    "Stack", "Queue", "Binary Tree", "Trie", "Graph", "Find Max", "Find Min"
]);

async function auditQuality() {
    console.log("--- Starting Quality Audit ---");

    const { data: problems, error } = await supabase
        .from('problems')
        .select('*');

    if (error) {
        console.error("Error fetching problems:", error);
        return;
    }

    const flagged: any[] = [];

    problems.forEach((p: any) => {
        const issues: string[] = [];

        // 1. Description Length
        if (p.description.length < 200) {
            issues.push(`Short Description (${p.description.length} chars)`);
        }

        // 2. Missing Constraints
        // Check for "Constraints" header or typical constraint notation (n <=, 1 <=)
        const hasConstraints = /Constraints|1 <=|n <=|length of/i.test(p.description);
        if (!hasConstraints) {
            issues.push("Missing Constraints");
        }

        // 3. Generic Title
        if (GENERIC_TITLES.has(p.title) || /^(Implement|Basic) [A-Za-z ]+$/.test(p.title)) {
            issues.push("Generic/Textbook Title");
        }

        // 4. Low Examples
        if (!p.examples || p.examples.length < 2) {
            issues.push("Few Examples (< 2)");
        }

        // 5. No Hints
        // Some good problems might not have hints, but combined with other flags it's a signal.
        if (!p.hints || p.hints.length === 0) {
            issues.push("No Hints");
        }

        if (issues.length > 0) {
            flagged.push({
                id: p.id,
                title: p.title,
                issues: issues,
                description_snippet: p.description.substring(0, 50) + "..."
            });
        }
    });

    console.log(`Found ${flagged.length} potential inferior problems.`);

    const reportPath = path.resolve(process.cwd(), 'inferior_problems_report.json');
    fs.writeFileSync(reportPath, JSON.stringify(flagged, null, 2));
    console.log(`Report written to: ${reportPath}`);
}

auditQuality();

import { createClient } from '@supabase/supabase-js';
import * as dotenv from 'dotenv';
import path from 'path';

dotenv.config({ path: path.resolve(process.cwd(), '.env.local') });

const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseKey = process.env.SUPABASE_SERVICE_ROLE_KEY!;
const supabase = createClient(supabaseUrl, supabaseKey);

// Simple Levenshtein distance for fuzzy matching
function levenshtein(a: string, b: string): number {
    const matrix = [];
    for (let i = 0; i <= b.length; i++) matrix[i] = [i];
    for (let j = 0; j <= a.length; j++) matrix[0][j] = j;

    for (let i = 1; i <= b.length; i++) {
        for (let j = 1; j <= a.length; j++) {
            if (b.charAt(i - 1) === a.charAt(j - 1)) {
                matrix[i][j] = matrix[i - 1][j - 1];
            } else {
                matrix[i][j] = Math.min(
                    matrix[i - 1][j - 1] + 1,
                    matrix[i][j - 1] + 1,
                    matrix[i - 1][j] + 1
                );
            }
        }
    }
    return matrix[b.length][a.length];
}

async function checkDuplicates() {
    console.log('--- Checking for Duplicates in Database ---');

    const { data: problems, error } = await supabase.from('problems').select('id, title, difficulty');

    if (error || !problems) {
        console.error("Failed to fetch problems:", error);
        return;
    }

    console.log(`Analyzing ${problems.length} problems...`);

    const exactMap = new Map<string, any[]>();
    const normalizedMap = new Map<string, any[]>();
    const duplicates: any[] = [];
    const fuzzyDuplicates: any[] = [];

    // 1. Exact and Normalized Checks
    for (const p of problems) {
        // Exact
        if (exactMap.has(p.title)) {
            duplicates.push({ original: exactMap.get(p.title)![0], duplicate: p, type: 'EXACT' });
        } else {
            exactMap.set(p.title, [p]);
        }

        // Normalized (lowercase, remove non-alphanumeric)
        const normalized = p.title.toLowerCase().replace(/[^a-z0-9]/g, '');
        if (normalizedMap.has(normalized)) {
            // Check if we haven't already caught it as EXACT
            const original = normalizedMap.get(normalized)![0];
            if (original.title !== p.title) {
                duplicates.push({ original, duplicate: p, type: 'NORMALIZED' });
            }
        } else {
            normalizedMap.set(normalized, [p]);
        }
    }

    // 2. Fuzzy Checks (O(N^2) but fine for <1000 items)
    // Only compare items that aren't already marked as duplicates
    const uniqueProblems = Array.from(exactMap.values()).map(v => v[0]);

    for (let i = 0; i < uniqueProblems.length; i++) {
        for (let j = i + 1; j < uniqueProblems.length; j++) {
            const p1 = uniqueProblems[i];
            const p2 = uniqueProblems[j];

            // Optimization: Length diff check
            if (Math.abs(p1.title.length - p2.title.length) > 3) continue;

            const dist = levenshtein(p1.title.toLowerCase(), p2.title.toLowerCase());
            // Threshold: 3 edits (e.g. "Two Sum" vs "Two Sums" is 1)
            // But ensure it's not just a short word like "BFS" vs "DFS" (dist 1)
            if (dist <= 2 && p1.title.length > 5) {
                fuzzyDuplicates.push({ p1, p2, dist });
            }
        }
    }

    // Report
    if (duplicates.length > 0) {
        console.log(`\n❌ Found ${duplicates.length} EXACT/NORMALIZED duplicates:`);
        duplicates.forEach(d => {
            console.log(`- [${d.type}] "${d.duplicate.title}" (ID: ${d.duplicate.id}) is duplicate of "${d.original.title}" (ID: ${d.original.id})`);
        });

        // Auto-delete option could be added here, but for now just reporting
    } else {
        console.log('\n✅ No EXACT or NORMALIZED duplicates found.');
    }

    if (fuzzyDuplicates.length > 0) {
        console.log(`\n⚠️ Found ${fuzzyDuplicates.length} POTENTIAL FUZZY duplicates (Manual review needed):`);
        fuzzyDuplicates.forEach(d => {
            console.log(`- "${d.p1.title}" vs "${d.p2.title}" (Dist: ${d.dist})`);
        });
    } else {
        console.log('\n✅ No POTENTIAL FUZZY duplicates found.');
    }
}

checkDuplicates();

