// Standalone Knowledge Ingestion Script
// Self-contained to avoid TS module resolution issues

import fs from 'fs';
import path from 'path';
import crypto from 'crypto';
import dotenv from 'dotenv';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { createClient } from '@supabase/supabase-js';

// Load environment variables from .env.local
const envPath = path.resolve(__dirname, '..', '.env.local');
console.log(`Loading env from: ${envPath}`);

if (fs.existsSync(envPath)) {
    dotenv.config({ path: envPath });
} else {
    console.warn(`⚠️  Warning: .env.local not found at ${envPath}`);
}

const RAW_DIR = path.join(__dirname, '..', 'src', 'data', 'dsa-knowledge', 'raw');
const OUTPUT_DIR = path.join(__dirname, '..', 'src', 'data', 'dsa-knowledge', 'embeddings');
const GEMINI_API_KEY = process.env.GEMINI_API_KEY;
const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SUPABASE_SERVICE_ROLE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY;

console.log('Configured API Key:', GEMINI_API_KEY ? `${GEMINI_API_KEY.substring(0, 8)}...` : 'NOT SET');

if (!GEMINI_API_KEY || GEMINI_API_KEY.startsWith('your_')) {
    console.error('❌ GEMINI_API_KEY is not set or is still using the placeholder in .env.local');
    process.exit(1);
}

if (!SUPABASE_URL || !SUPABASE_SERVICE_ROLE_KEY) {
    console.warn('⚠️  Supabase credentials not found. DB ingestion will be skipped.');
}

const genAI = new GoogleGenerativeAI(GEMINI_API_KEY);
const embeddingModel = genAI.getGenerativeModel({ model: "gemini-embedding-001" });

// --- Types ---
interface KnowledgeChunk {
    id: string;
    topic: string;
    subtopic: string;
    title: string;
    content: string;
    keywords: string[];
    difficulty: 'easy' | 'medium' | 'hard';
    patterns: string[];
    timeComplexity?: string;
    spaceComplexity?: string;
    source?: 'file' | 'db';
}

interface EmbeddedChunk extends KnowledgeChunk {
    embedding: number[];
    embeddingModel: string;
}

// --- Helpers ---
function extractKeywords(text: string): string[] {
    const stopWords = new Set([
        'the', 'a', 'an', 'is', 'are', 'was', 'were', 'to', 'of', 'in', 'for', 'on', 'with'
    ]);
    return text
        .toLowerCase()
        .replace(/[^a-z0-9\s]/g, ' ')
        .split(/\s+/)
        .filter(word => word.length > 3 && !stopWords.has(word))
        .filter((word, index, arr) => arr.indexOf(word) === index);
}

function chunkText(text: string, title: string, topic: string): KnowledgeChunk[] {
    const chunks: KnowledgeChunk[] = [];
    const sections = text.split(/^##\s+/m).filter(s => s.trim().length > 0);

    for (const section of sections) {
        const lines = section.split('\n');
        const sectionTitle = lines[0].trim().replace(/^#+\s*/, '');
        const content = lines.slice(1).join('\n').trim();

        if (content.length < 50) continue;

        let difficulty: 'easy' | 'medium' | 'hard' = 'medium';
        const lower = content.toLowerCase();
        if (lower.includes('hard') || lower.includes('dp')) difficulty = 'hard';
        if (lower.includes('basic') || lower.includes('easy')) difficulty = 'easy';

        const patterns = [];
        if (lower.includes('two pointer')) patterns.push('two-pointers');
        if (lower.includes('sliding window')) patterns.push('sliding-window');
        if (lower.includes('dfs')) patterns.push('dfs');
        if (lower.includes('bfs')) patterns.push('bfs');

        const id = crypto.createHash('md5').update(`${topic}-${sectionTitle}`).digest('hex');

        chunks.push({
            id,
            topic,
            subtopic: sectionTitle.toLowerCase().replace(/\s+/g, '-'),
            title: `${topic}: ${sectionTitle}`,
            content,
            keywords: extractKeywords(content),
            difficulty,
            patterns,
            timeComplexity: lower.match(/O\([^)]+\)/)?.[0],
            spaceComplexity: lower.match(/space\s+complexity[:\s]+(O\([^)]+\))/i)?.[1],
            source: 'file'
        });
    }
    return chunks;
}

async function getEmbedding(text: string): Promise<number[]> {
    try {
        const result = await embeddingModel.embedContent(text);
        return result.embedding.values;
    } catch (error) {
        console.error('Embedding error:', error);
        throw error;
    }
}

// --- Main ---
async function main() {
    console.log('🚀 Starting Knowledge Ingestion (Hybrid: Files + DB)...');

    const embeddedChunks: EmbeddedChunk[] = [];
    let totalProcessed = 0;

    // 1. Process Local Files
    if (fs.existsSync(RAW_DIR)) {
        const files = fs.readdirSync(RAW_DIR).filter(f => f.endsWith('.md'));
        console.log(`\n📂 Found ${files.length} local markdown files.`);

        for (const file of files) {
            console.log(`Processing file: ${file}...`);
            const content = fs.readFileSync(path.join(RAW_DIR, file), 'utf-8');
            const topic = file.replace('.md', '').toUpperCase(); // Use filename as topic
            const titleLine = content.split('\n')[0].replace('# ', ''); // First line as main title

            const chunks = chunkText(content, titleLine, topic);

            for (const chunk of chunks) {
                process.stdout.write('.');
                try {
                    const embedding = await getEmbedding(chunk.content);
                    embeddedChunks.push({
                        ...chunk,
                        embedding,
                        embeddingModel: 'text-embedding-004'
                    });
                    await new Promise(r => setTimeout(r, 500)); // Rate limit
                } catch (e) {
                    process.stdout.write('X');
                }
            }
            console.log(' Done.');
            totalProcessed += chunks.length;
        }
    } else {
        console.warn(`Raw directory not found: ${RAW_DIR}`);
    }

    // 2. Process Supabase DB Records
    if (SUPABASE_URL && SUPABASE_SERVICE_ROLE_KEY) {
        console.log(`\n🗄️  Connecting to Supabase...`);
        const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY);

        const { data: dbChunks, error } = await supabase
            .from('knowledge_chunks') // Query legacy table or dsa_knowledge? Script logic says knowledge_chunks per admin page
            .select('*')
            .eq('status', 'active');

        if (error) {
            console.error('❌ Failed to fetch from Supabase:', error.message);
        } else if (dbChunks && dbChunks.length > 0) {
            console.log(`Found ${dbChunks.length} active chunks in DB.`);

            for (const item of dbChunks) {
                process.stdout.write('+');

                // If ID collisions are a concern, handle appropriately. DB IDs are UUIDs, File IDs are MD5s.
                // Assuming no collisions for now.

                // Check if we need to generate embedding (if stored in DB, we could reuse, but for now re-gen to be safe)
                // Optionally update DB with embedding if missing?

                try {
                    const embedding = await getEmbedding(item.content);

                    embeddedChunks.push({
                        id: item.id,
                        topic: item.topic.toUpperCase(),
                        subtopic: item.subtopic,
                        title: `${item.topic}: ${item.subtopic}`,
                        content: item.content,
                        keywords: item.keywords || extractKeywords(item.content),
                        difficulty: item.difficulty || 'medium',
                        patterns: [], // DB doesn't have patterns col yet usually
                        source: 'db',
                        embedding,
                        embeddingModel: 'text-embedding-004'
                    });

                    // Optional: Update DB with embedding if you want to support pgvector later
                    // await supabase.from('knowledge_chunks').update({ embedding }).eq('id', item.id);

                    await new Promise(r => setTimeout(r, 500));
                } catch (e) {
                    process.stdout.write('X');
                }
            }
            console.log(' Done.');
            totalProcessed += dbChunks.length;
        } else {
            console.log('No active chunks found in DB.');
        }
    }

    // Save to disk
    if (!fs.existsSync(OUTPUT_DIR)) {
        fs.mkdirSync(OUTPUT_DIR, { recursive: true });
    }

    const outputPath = path.join(OUTPUT_DIR, 'embeddings.json');
    fs.writeFileSync(outputPath, JSON.stringify(embeddedChunks, null, 2));

    console.log('\n✨ Ingestion Complete!');
    console.log(`Total Chunks: ${embeddedChunks.length}`);
    console.log(`Saved to ${outputPath}`);
}

main().catch(console.error);

// scripts/push-embeddings-to-db.ts
// Use this script to populate the 'knowledge_chunks' table from your local 'embeddings.json'

import fs from 'fs';
import path from 'path';
import dotenv from 'dotenv';
import { createClient } from '@supabase/supabase-js';

// 1. Load Environment Variables
const envPath = path.resolve(__dirname, '..', '.env.local');
console.log(`Loading env from: ${envPath}`);

if (fs.existsSync(envPath)) {
    dotenv.config({ path: envPath });
} else {
    console.warn(`⚠️  Warning: .env.local not found at ${envPath}`);
}

const SUPABASE_URL = process.env.NEXT_PUBLIC_SUPABASE_URL;
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_ROLE_KEY; // Use Service Key for Admin Write Access

if (!SUPABASE_URL || !SUPABASE_SERVICE_KEY) {
    console.error('❌ Supabase credentials missing.');
    console.error('Ensure NEXT_PUBLIC_SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are in .env.local');
    process.exit(1);
}

// 2. Initialize Supabase Admin Client
const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY, {
    auth: {
        autoRefreshToken: false,
        persistSession: false
    }
});

const EMBEDDINGS_PATH = path.join(__dirname, '..', 'src', 'data', 'dsa-knowledge', 'embeddings', 'embeddings.json');

async function main() {
    console.log('🚀 Starting DB Sync...');

    if (!fs.existsSync(EMBEDDINGS_PATH)) {
        console.error(`❌ No embeddings found at ${EMBEDDINGS_PATH}`);
        console.error('Run "npm run ingest" first to generate them.');
        process.exit(1);
    }

    // 3. Read Local Embeddings
    const rawData = fs.readFileSync(EMBEDDINGS_PATH, 'utf-8');
    const chunks = JSON.parse(rawData);
    console.log(`📂 Loaded ${chunks.length} chunks from disk.`);

    let successCount = 0;
    let errorCount = 0;

    // 4. Batch Insert/Upsert
    // We do this individually or in small batches to handle potential size limits or errors gracefully
    for (const chunk of chunks) {
        try {
            const { error } = await supabase
                .from('knowledge_chunks')
                .upsert({
                    // If your JSON has 'id', use it. Otherwise, let DB generate or use composite key?
                    // The ingest script generates a deterministic MD5 'id', so we can use that for upsert.
                    id: chunk.id,
                    topic: chunk.topic,
                    subtopic: chunk.subtopic,
                    content: chunk.content,
                    keywords: chunk.keywords,
                    difficulty: chunk.difficulty,
                    embedding: chunk.embedding, // Vector column
                    source: 'auto-ingest',
                    status: 'active'
                    // updated_at: new Date().toISOString() // Removed to avoid schema mismatch errors if column missing
                }, { onConflict: 'id' });

            if (error) {
                console.error(`❌ Failed to insert ${chunk.title}:`, error.message);
                errorCount++;
            } else {
                process.stdout.write('.');
                successCount++;
            }
        } catch (err: unknown) {
            console.error(`❌ Exception for ${chunk.title}:`, (err as any).message);
            errorCount++;
        }
    }

    console.log('\n\n✅ Sync Complete!');
    console.log(`Success: ${successCount}`);
    console.log(`Errors: ${errorCount}`);
}

main().catch(console.error);

