'use client';

import { useAuth } from '@/components/auth/AuthProvider';
import { useRouter, usePathname } from 'next/navigation';
import { Button } from '@/components/ui/button';
import {
    DropdownMenu,
    DropdownMenuContent,
    DropdownMenuItem,
    DropdownMenuLabel,
    DropdownMenuSeparator,
    DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu';
import { LogOut, Settings, BarChart, Home, Mic, Shield, Flag } from 'lucide-react';
import Link from 'next/link';
import { DemoBanner } from '@/components/demo/DemoBanner';
import { isDemoMode } from '@/lib/demo/manager';
import { cn } from '@/lib/utils';
import { useEffect, useState } from 'react';
import { useAdmin } from '@/hooks/useAdmin';

export function Navbar() {
    const { user, signOut, loading, isConfigured } = useAuth();
    const router = useRouter();
    const pathname = usePathname();
    const [isDemo, setIsDemo] = useState(false);
    const { isAdmin } = useAdmin();

    useEffect(() => {
        setIsDemo(isDemoMode());
    }, [pathname]); // Re-check on navigation

    const handleLogout = async () => {
        await signOut();
        router.push('/');
    };

    // Hide navbar on certain pages
    const hideNavbarRoutes = ['/login'];
    if (hideNavbarRoutes.includes(pathname)) {
        return null;
    }

    return (
        <>
            <header className="fixed top-0 left-0 right-0 z-[100] flex flex-col">
                <DemoBanner />
                <nav className="bg-slate-900/95 backdrop-blur-md border-b border-slate-800 h-16 shadow-2xl">
                    <div className="w-full px-6 lg:px-8">
                        <div className="flex items-center justify-between h-16">
                            {/* Logo */}
                            {/* Logo */}
                            <button
                                onClick={() => router.push('/')}
                                className="flex items-center gap-3 font-bold text-xl text-white hover:text-blue-400 transition-colors group shrink-0"
                            >
                                <img
                                    src="/icon-192x192.png"
                                    alt="AlgoMind Logo"
                                    className="w-8 h-8 group-hover:scale-110 transition-transform drop-shadow-[0_0_8px_rgba(59,130,246,0.5)] rounded-lg"
                                />
                                <span className="tracking-tight font-black bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">AlgoMind</span>
                            </button>

                            {/* Navigation Links */}
                            {user && (
                                <div className="hidden md:flex items-center gap-6">
                                    <Link
                                        href="/"
                                        className={`flex items-center gap-2 text-sm font-bold transition-colors ${pathname === '/' ? 'text-blue-400' : 'text-slate-400 hover:text-white'
                                            }`}
                                    >
                                        <Home className="w-4 h-4" />
                                        Home
                                    </Link>
                                    <Link
                                        href="/dashboard"
                                        className={`flex items-center gap-2 text-sm font-bold transition-colors ${pathname === '/dashboard' ? 'text-blue-400' : 'text-slate-400 hover:text-white'
                                            }`}
                                    >
                                        <BarChart className="w-4 h-4" />
                                        Dashboard
                                    </Link>
                                    <Link
                                        href="/interview"
                                        className={`flex items-center gap-2 text-sm font-bold transition-colors ${pathname === '/interview' ? 'text-blue-400' : 'text-slate-400 hover:text-white'
                                            }`}
                                    >
                                        <Mic className="w-4 h-4" />
                                        Practice
                                    </Link>
                                </div>
                            )}

                            {/* User Menu */}
                            <div className="flex items-center gap-4">
                                {loading ? (
                                    <div className="w-8 h-8 rounded-full bg-slate-800 animate-pulse" />
                                ) : user ? (
                                    <DropdownMenu>
                                        <DropdownMenuTrigger asChild>
                                            <button className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-800/50 hover:bg-slate-700 transition-all border border-slate-700 hover:border-slate-500 shadow-lg">
                                                <div className="w-7 h-7 rounded-full bg-gradient-to-br from-blue-600 to-purple-600 flex items-center justify-center text-white font-black text-xs">
                                                    {user.email?.[0].toUpperCase()}
                                                </div>
                                                <span className="text-xs font-bold text-slate-200 hidden sm:block max-w-[150px] truncate">
                                                    {user.user_metadata?.full_name || user.email?.split('@')[0]}
                                                </span>
                                            </button>
                                        </DropdownMenuTrigger>

                                        <DropdownMenuContent
                                            align="end"
                                            className="w-56 bg-slate-900 border-slate-800 shadow-2xl p-2 rounded-2xl"
                                        >
                                            <DropdownMenuLabel className="px-2 py-2">
                                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-500 block mb-1">Authenticated as</span>
                                                <span className="text-white text-sm font-bold block truncate">{user.email}</span>
                                            </DropdownMenuLabel>

                                            <DropdownMenuSeparator className="bg-slate-800 my-1" />

                                            <DropdownMenuItem
                                                onClick={() => router.push('/dashboard')}
                                                className="text-slate-400 hover:bg-slate-800 hover:text-white cursor-pointer focus:bg-slate-800 rounded-xl px-3 py-2 text-xs font-bold"
                                            >
                                                <BarChart className="mr-2 h-4 w-4" />
                                                Dashboard
                                            </DropdownMenuItem>

                                            <DropdownMenuItem
                                                onClick={() => router.push('/settings')}
                                                className="text-slate-400 hover:bg-slate-800 hover:text-white cursor-pointer focus:bg-slate-800 rounded-xl px-3 py-2 text-xs font-bold"
                                            >
                                                <Settings className="mr-2 h-4 w-4" />
                                                Settings
                                            </DropdownMenuItem>

                                            {/* Admin button - only visible to admins */}
                                            {isAdmin && (
                                                <>
                                                    <DropdownMenuItem
                                                        onClick={() => router.push('/admin/knowledge')}
                                                        className="text-emerald-400 hover:bg-emerald-900/30 hover:text-emerald-300 cursor-pointer focus:bg-emerald-800 rounded-xl px-3 py-2 text-xs font-bold"
                                                    >
                                                        <Shield className="mr-2 h-4 w-4" />
                                                        Knowledge Base
                                                    </DropdownMenuItem>
                                                    <DropdownMenuItem
                                                        onClick={() => router.push('/admin/features')}
                                                        className="text-purple-400 hover:bg-purple-900/30 hover:text-purple-300 cursor-pointer focus:bg-purple-800 rounded-xl px-3 py-2 text-xs font-bold"
                                                    >
                                                        <Flag className="mr-2 h-4 w-4" />
                                                        Feature Flags
                                                    </DropdownMenuItem>
                                                </>
                                            )}

                                            <DropdownMenuSeparator className="bg-slate-800 my-1" />

                                            <DropdownMenuItem
                                                onClick={handleLogout}
                                                className="text-red-400 hover:bg-red-500 hover:text-white cursor-pointer focus:bg-red-800 rounded-xl px-3 py-2 text-xs font-bold"
                                            >
                                                <LogOut className="mr-2 h-4 w-4" />
                                                Sign Out
                                            </DropdownMenuItem>
                                        </DropdownMenuContent>
                                    </DropdownMenu>
                                ) : (
                                    <Button
                                        onClick={() => router.push('/login')}
                                        className="bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 rounded-xl font-bold h-9 px-5"
                                    >
                                        Sign In
                                    </Button>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Auth not configured warning */}
                    {!isConfigured && (
                        <div className="bg-yellow-500/10 border-t border-yellow-500/20 py-1 px-4 text-center overflow-x-auto">
                            <p className="text-[10px] font-black uppercase text-yellow-500 whitespace-nowrap">
                                ⚠️ Guest Mode Active (Local Storage)
                            </p>
                        </div>
                    )}
                </nav>
            </header>
            {/* Spacer to push content down - dynamic height based on demo mode */}
            <div className={cn(
                "w-full transition-all duration-300",
                isDemo ? "h-[104px]" : "h-16"
            )} />
        </>
    );
}

'use client';

import { motion } from 'framer-motion';
import { useState, useEffect, useRef } from 'react';

interface IntroAnimationProps {
    onComplete: () => void;
}

export function IntroAnimation({ onComplete }: IntroAnimationProps) {
    const [step, setStep] = useState(0);
    const particlesRef = useRef(
        [...Array(20)].map(() => ({
            x: Math.random(), // normalized 0-1
            y: Math.random(), // normalized 0-1
            duration: 3 + Math.random() * 2,
            delay: Math.random() * 2,
        }))
    );

    useEffect(() => {
        const timers = [
            setTimeout(() => setStep(1), 1000),   // Brain appears
            setTimeout(() => setStep(2), 2500),   // Nodes build
            setTimeout(() => setStep(3), 4000),   // CTA appears
        ];

        // Keyboard listener to skip animation
        const handleKeyPress = (e: KeyboardEvent) => {
            if (e.key === 'Escape' || e.key === ' ' || e.key === 'Enter') {
                e.preventDefault();
                onComplete();
            }
        };

        window.addEventListener('keydown', handleKeyPress);

        return () => {
            timers.forEach(clearTimeout);
            window.removeEventListener('keydown', handleKeyPress);
        };
    }, [onComplete]);

    return (
        <div className="fixed inset-0 z-50 bg-gradient-to-br from-slate-900 via-blue-900 to-purple-900 flex items-center justify-center overflow-hidden">
            {/* Background gradient orbs */}
            <div className="absolute inset-0 overflow-hidden">
                <motion.div
                    className="absolute w-96 h-96 rounded-full bg-blue-500/20 blur-3xl"
                    animate={{
                        x: [0, 100, 0],
                        y: [0, -50, 0],
                    }}
                    transition={{ duration: 8, repeat: Infinity, ease: "easeInOut" }}
                    style={{ top: '10%', left: '10%' }}
                />
                <motion.div
                    className="absolute w-96 h-96 rounded-full bg-purple-500/20 blur-3xl"
                    animate={{
                        x: [0, -100, 0],
                        y: [0, 50, 0],
                    }}
                    transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
                    style={{ bottom: '10%', right: '10%' }}
                />
            </div>

            {/* User Silhouette (0-1s) */}
            <motion.div
                initial={{ opacity: 0, scale: 0.5 }}
                animate={{ opacity: step >= 0 ? 1 : 0, scale: step >= 0 ? 1 : 0.5 }}
                transition={{ duration: 1 }}
                className="absolute"
            >
                <div className="w-32 h-32 rounded-full bg-gradient-to-br from-blue-400 to-purple-600 opacity-20" />
            </motion.div>

            {/* Brain Network (1-2.5s) */}
            <motion.div
                initial={{ opacity: 0, scale: 0 }}
                animate={{ opacity: step >= 1 ? 1 : 0, scale: step >= 1 ? 1 : 0 }}
                transition={{ duration: 1.5 }}
                className="absolute"
            >
                <svg width="300" height="300" viewBox="0 0 300 300">
                    {/* Central node */}
                    <motion.circle
                        cx="150"
                        cy="150"
                        r="20"
                        fill="url(#centerGradient)"
                        initial={{ r: 0 }}
                        animate={{ r: step >= 1 ? 20 : 0 }}
                        transition={{ duration: 0.5 }}
                        filter="url(#glow)"
                    />

                    {/* Connecting nodes */}
                    {[0, 60, 120, 180, 240, 300].map((angle, i) => {
                        const x = 150 + Math.cos((angle * Math.PI) / 180) * 80;
                        const y = 150 + Math.sin((angle * Math.PI) / 180) * 80;

                        return (
                            <g key={i}>
                                <motion.line
                                    x1="150"
                                    y1="150"
                                    x2={x}
                                    y2={y}
                                    stroke="url(#lineGradient)"
                                    strokeWidth="3"
                                    initial={{ pathLength: 0, opacity: 0 }}
                                    animate={{
                                        pathLength: step >= 1 ? 1 : 0,
                                        opacity: step >= 1 ? 1 : 0
                                    }}
                                    transition={{ duration: 0.8, delay: i * 0.1 }}
                                />
                                <motion.circle
                                    cx={x}
                                    cy={y}
                                    r="14"
                                    fill="url(#nodeGradient)"
                                    initial={{ scale: 0, opacity: 0 }}
                                    animate={{
                                        scale: step >= 1 ? 1 : 0,
                                        opacity: step >= 1 ? 1 : 0
                                    }}
                                    transition={{ duration: 0.3, delay: i * 0.1 + 0.5 }}
                                    filter="url(#glow)"
                                />
                            </g>
                        );
                    })}

                    {/* Gradients */}
                    <defs>
                        <linearGradient id="centerGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                            <stop offset="0%" stopColor="#3b82f6" />
                            <stop offset="100%" stopColor="#8b5cf6" />
                        </linearGradient>
                        <linearGradient id="nodeGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                            <stop offset="0%" stopColor="#8b5cf6" />
                            <stop offset="100%" stopColor="#ec4899" />
                        </linearGradient>
                        <linearGradient id="lineGradient" x1="0%" y1="0%" x2="100%" y2="100%">
                            <stop offset="0%" stopColor="#60a5fa" />
                            <stop offset="100%" stopColor="#a78bfa" />
                        </linearGradient>
                        <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
                            <feGaussianBlur stdDeviation="3" result="coloredBlur" />
                            <feMerge>
                                <feMergeNode in="coloredBlur" />
                                <feMergeNode in="SourceGraphic" />
                            </feMerge>
                        </filter>
                    </defs>
                </svg>
            </motion.div>

            {/* Logo Text */}
            <motion.div
                initial={{ opacity: 0, y: -30 }}
                animate={{ opacity: step >= 1 ? 1 : 0, y: step >= 1 ? 0 : -30 }}
                transition={{ duration: 0.8, delay: 0.5 }}
                className="absolute top-1/4"
            >
                <h1 className="text-6xl font-black text-white tracking-tight">
                    Algo<span className="text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-purple-400">Mind</span>
                </h1>
            </motion.div>

            {/* DSA Labels (2.5-4s) */}
            <motion.div
                initial={{ opacity: 0, y: 50 }}
                animate={{ opacity: step >= 2 ? 1 : 0, y: step >= 2 ? 0 : 50 }}
                transition={{ duration: 0.8 }}
                className="absolute bottom-1/3 flex gap-3 flex-wrap justify-center max-w-lg"
            >
                {['Arrays', 'Trees', 'Graphs', 'Dynamic Programming', 'Recursion', 'Sorting'].map((label, i) => (
                    <motion.span
                        key={label}
                        initial={{ opacity: 0, scale: 0.8 }}
                        animate={{ opacity: step >= 2 ? 1 : 0, scale: step >= 2 ? 1 : 0.8 }}
                        transition={{ delay: i * 0.08 }}
                        className="px-4 py-2 bg-white/10 backdrop-blur-sm border border-white/20 rounded-full text-white text-sm font-medium"
                    >
                        {label}
                    </motion.span>
                ))}
            </motion.div>

            {/* Tagline */}
            <motion.p
                initial={{ opacity: 0 }}
                animate={{ opacity: step >= 2 ? 1 : 0 }}
                transition={{ duration: 0.8, delay: 0.3 }}
                className="absolute bottom-1/4 text-slate-300 text-lg font-medium"
            >
                AI-Powered DSA Interview Practice
            </motion.p>

            {/* CTA (4-5s) */}
            <motion.div
                initial={{ opacity: 0, scale: 0.8 }}
                animate={{ opacity: step >= 3 ? 1 : 0, scale: step >= 3 ? 1 : 0.8 }}
                transition={{ duration: 0.6 }}
                className="absolute bottom-16"
            >
                <button
                    onClick={onComplete}
                    className="group relative px-10 py-4 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-2xl font-bold text-lg shadow-2xl hover:shadow-blue-500/25 hover:scale-105 transition-all duration-300 overflow-hidden"
                >
                    <span className="relative z-10">Start Practicing</span>
                    <div className="absolute inset-0 bg-gradient-to-r from-blue-500 to-purple-500 opacity-0 group-hover:opacity-100 transition-opacity" />
                </button>
            </motion.div>

            {/* Skip button */}
            <button
                onClick={onComplete}
                className="absolute top-8 right-8 text-white/50 hover:text-white text-sm font-medium transition-colors"
            >
                Skip (ESC / Space / Enter) →
            </button>

            {/* Animated particles */}
            <div className="absolute inset-0 pointer-events-none">
                {particlesRef.current.map((particle, i) => (
                    <motion.div
                        key={i}
                        className="absolute w-1 h-1 bg-white/30 rounded-full"
                        initial={{
                            x: particle.x * (typeof window !== 'undefined' ? window.innerWidth : 1000),
                            y: particle.y * (typeof window !== 'undefined' ? window.innerHeight : 800),
                        }}
                        animate={{
                            y: [null, -100],
                            opacity: [0, 1, 0],
                        }}
                        transition={{
                            duration: particle.duration,
                            repeat: Infinity,
                            delay: particle.delay,
                        }}
                    />
                ))}
            </div>
        </div>
    );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { isDemoMode, enableDemoMode, disableDemoMode } from '@/lib/demo/manager';
import { resetOnboarding, shouldShowOnboarding, markOnboardingComplete } from '@/lib/onboarding/manager';
import { useAuth } from '@/components/auth/AuthProvider';
import { getSupabase } from '@/lib/supabase/client';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { RotateCcw, Trash2, ArrowLeft, User, LogOut, Database, Shield, Play, FlaskConical } from 'lucide-react';
import Link from 'next/link';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';

import { VoiceSettings } from './VoiceSettings';

export function SettingsPanel() {
    const [introEnabled, setIntroEnabled] = useState(false);
    const [demoMode, setDemoMode] = useState(false);
    const [mounted, setMounted] = useState(false);
    const [isClearing, setIsClearing] = useState(false);
    const { user, signOut, isConfigured } = useAuth();
    const router = useRouter();

    useEffect(() => {
        setMounted(true);
        setIntroEnabled(shouldShowOnboarding());
        setDemoMode(isDemoMode());

        const handleDemoChange = (e: CustomEvent<{ enabled: boolean }>) => {
            setDemoMode(e.detail.enabled);
        };

        window.addEventListener('demo-mode-changed', handleDemoChange as EventListener);
        return () => {
            window.removeEventListener('demo-mode-changed', handleDemoChange as EventListener);
        };
    }, []);

    const toggleIntro = () => {
        // ... (existing toggleIntro logic)
        if (introEnabled) {
            markOnboardingComplete();
            toast.success('Intro animation disabled for next visit');
        } else {
            resetOnboarding();
            toast.success('Intro animation enabled for next visit');
        }
        setIntroEnabled(!introEnabled);
    };

    const handleExitDemo = () => {
        disableDemoMode();
        window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));
        toast.success('Demo mode disabled');
        router.refresh();
    };

    const handleStartDemoTour = () => {
        // Event listener in TourContext checks this
        if (!demoMode) {
            enableDemoMode();
            window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: true } }));
        }
        window.dispatchEvent(new CustomEvent('start-tour'));
    };

    const handleClearData = async () => {
        if (!confirm('Are you sure? This will delete ALL your interview sessions and progress. This cannot be undone!')) {
            return;
        }

        setIsClearing(true);

        try {
            // Clear localStorage
            localStorage.clear();
            // Force disable demo mode in state/UI too
            disableDemoMode();

            // If authenticated and Supabase is configured, clear database
            if (user && isConfigured) {
                const supabase = getSupabase();
                if (supabase) {
                    // Delete assessments first (foreign key constraint)
                    await supabase
                        .from('assessments')
                        .delete()
                        .eq('user_id', user.id);

                    // Delete sessions
                    await supabase
                        .from('interview_sessions')
                        .delete()
                        .eq('user_id', user.id);
                }
            }

            toast.success('All data cleared successfully!');
            router.refresh();
        } catch (error) {
            console.error('Failed to clear data:', error);
            toast.error('Failed to clear data. Please try again.');
        } finally {
            setIsClearing(false);
        }
    };

    const handleSignOut = async () => {
        disableDemoMode(); // Ensure demo mode is off on logout
        window.dispatchEvent(new CustomEvent('demo-mode-changed', { detail: { enabled: false } }));
        await signOut();
        toast.success('Signed out successfully');
        router.push('/');
    };

    if (!mounted) return null;

    return (
        <div className="space-y-6">
            {/* Back Link */}
            <Link href="/" className="inline-flex items-center text-slate-400 hover:text-white transition-colors">
                <ArrowLeft className="w-4 h-4 mr-2" />
                Back to Home
            </Link>

            <h1 className="text-3xl font-bold text-white">Settings</h1>

            {/* User Profile Card */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white flex items-center gap-2">
                        <User className="w-5 h-5" />
                        Profile
                    </CardTitle>
                    <CardDescription>Your account information</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    {user ? (
                        <>
                            <div className="flex items-center gap-4 p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                                {user.user_metadata?.avatar_url ? (
                                    <img
                                        src={user.user_metadata.avatar_url}
                                        alt={user.email || 'User'}
                                        className="w-16 h-16 rounded-full ring-2 ring-slate-600"
                                    />
                                ) : (
                                    <div className="w-16 h-16 rounded-full bg-gradient-to-br from-blue-500 to-purple-600 flex items-center justify-center text-white text-2xl font-bold">
                                        {user.email?.[0].toUpperCase()}
                                    </div>
                                )}
                                <div className="min-w-0 flex-1">
                                    <p className="text-lg font-semibold text-white truncate">
                                        {user.user_metadata?.full_name || 'AlgoMind User'}
                                    </p>
                                    <p className="text-slate-400 truncate">{user.email}</p>
                                </div>
                            </div>

                            <Button
                                onClick={handleSignOut}
                                variant="destructive"
                                className="w-full bg-red-600/10 hover:bg-red-600 text-red-500 hover:text-white border border-red-900/50 transition-all font-bold"
                            >
                                <LogOut className="w-4 h-4 mr-2" />
                                Sign Out
                            </Button>
                        </>
                    ) : (
                        <div className="p-4 rounded-xl bg-slate-800/50 border border-slate-700 text-center">
                            <p className="text-slate-400 mb-3">You're using AlgoMind as a guest</p>
                            <Button onClick={() => router.push('/login')}>
                                Sign In for Cloud Sync
                            </Button>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Voice Settings */}
            <VoiceSettings />

            {/* Storage Info */}
            <Card className="bg-slate-900/50 border-slate-800">
                <CardHeader>
                    <CardTitle className="text-white flex items-center gap-2">
                        <Database className="w-5 h-5" />
                        Data Storage
                    </CardTitle>
                    <CardDescription>Where your data is stored</CardDescription>
                </CardHeader>
                <CardContent>
                    <div className="p-4 rounded-xl bg-slate-800/50 border border-slate-700">
                        <div className="flex items-center gap-2 mb-2">
                            <Shield className={`w-4 h-4 ${isConfigured ? 'text-emerald-400' : 'text-yellow-400'}`} />
                            <span className="font-medium text-white">
                                {isConfigured ? 'Cloud Storage (Supabase)' : 'Local Storage Only'}
                            </span>
                        </div>
                        <p className="text-sm text-slate-400">
                            {isConfigured
                                ? 'Your data is securely stored in the cloud and syncs across devices.'
                                : 'Data is stored locally in your browser. Sign in to enable cloud sync.'}
                        </p>
                    </div>
                </CardContent>
            </Card>

            {/* App Settings */}
