    });
});

import { CognitiveSkill, SkillDefinition } from '@/types/assessment';
import { SKILL_DEFINITIONS } from './skill-registry';
import { ConversationTurn, generateAssessmentPrompt } from './prompts';
import { calculateConfidence } from './confidence-calculator';

export interface SkillScore {
    score: number;
    evidence: string[];
    strengths: string[];
    improvements: string[];
    confidence: number;
}

export interface AssessmentResult {
    sessionId: string;
    timestamp: Date;
    problem: { title: string; description: string; difficulty: string };
    skills: Record<CognitiveSkill, SkillScore>;
    overallFeedback: string;
    nextSteps: string[];
    knowledgeGaps?: string[];
    modelUsed?: string;
}

interface ParsedAssessmentResponse {
    skills: Record<string, {
        score: number;
        evidence: string[];
        strengths: string[];
        improvements: string[];
    }>;
    overallFeedback: string;
    nextSteps: string[];
    knowledgeGaps?: string[];
}

export class CognitiveAnalyzer {
    private maxRetries = 3;
    private retryDelayMs = 1000;

    /**
     * Main entry point for analyzing an interview session
     * Implements retry logic to handle model fallback
     */
    async analyze(
        sessionId: string,
        problem: { title: string; description: string; difficulty: string },
        transcript: ConversationTurn[]
    ): Promise<AssessmentResult> {
        const prompt = generateAssessmentPrompt(problem, transcript, SKILL_DEFINITIONS);

        let lastError: Error | null = null;

        for (let attempt = 1; attempt <= this.maxRetries; attempt++) {
            try {
                const rawResponse = await this.callAI(prompt);
                const parsedData = this.parseResponse(rawResponse) as unknown as ParsedAssessmentResponse;

                // Post-process: calculate confidence and finalize structure
                const sessionConfidence = calculateConfidence(transcript, parsedData);

                const finalizedSkills: Record<string, SkillScore> = {};
                Object.keys(SKILL_DEFINITIONS).forEach((skillId) => {
                    const data = parsedData.skills[skillId] || {
                        score: 5,
                        evidence: [],
                        strengths: [],
                        improvements: []
                    };
                    finalizedSkills[skillId] = {
                        ...data,
                        confidence: sessionConfidence
                    };
                });

                return {
                    sessionId,
                    timestamp: new Date(),
                    problem,
                    skills: finalizedSkills,
                    overallFeedback: parsedData.overallFeedback || "No feedback generated.",
                    nextSteps: parsedData.nextSteps || ["Review the session manually."],
                    knowledgeGaps: parsedData.knowledgeGaps || []
                };

            } catch (error: unknown) {
                lastError = error instanceof Error ? error : new Error(String(error));
                console.warn(`Assessment attempt ${attempt} failed:`, lastError.message);

                if (attempt < this.maxRetries) {
                    // Wait before retrying (exponential backoff)
                    const delay = this.retryDelayMs * Math.pow(2, attempt - 1);
                    await new Promise(resolve => setTimeout(resolve, delay));
                }
            }
        }

        // All retries exhausted
        console.error(`Assessment failed after ${this.maxRetries} attempts`);
        throw new Error(`Assessment failed after ${this.maxRetries} attempts. Last error: ${lastError?.message}`);
    }

    private async callAI(prompt: string): Promise<string> {
        // Use UnifiedAIClient directly instead of internal API fetch
        const { getAIClient } = await import('@/lib/ai/client');
        const client = getAIClient();

        const result = await client.generateCompletion(
            [{ role: 'user', content: prompt }],
            {
                preferredProvider: 'gemini', // Deep analysis
                category: 'intelligence',
                systemPrompt: "You are a professional assessment engine. Return only valid JSON.",
                maxTokens: 4096,
                estimatedTokens: 2000
            }
        );

        if (!result.success || !result.response) {
            throw new Error(`AI Analysis failed: ${result.error}`);
        }

        return result.response;
    }

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    private parseResponse(raw: string): unknown {
        // 1. Strip markdown fences more thoroughly
        let jsonString = raw
            .replace(/^```(?:json)?\s*/i, '')  // Opening fence
            .replace(/```\s*$/i, '')           // Closing fence
            .trim();

        // 2. Try to find JSON object boundaries if wrapped in extra text
        const jsonStart = jsonString.indexOf('{');
        const jsonEnd = jsonString.lastIndexOf('}');

        if (jsonStart !== -1 && jsonEnd !== -1 && jsonEnd > jsonStart) {
            jsonString = jsonString.slice(jsonStart, jsonEnd + 1);
        }

        // 3. Check if response appears truncated (no closing brace or ends abruptly)
        const openBraces = (jsonString.match(/{/g) || []).length;
        const closeBraces = (jsonString.match(/}/g) || []).length;

        if (openBraces !== closeBraces) {
            console.error("AI response appears truncated - mismatched braces:", { openBraces, closeBraces });
            throw new Error(`AI response truncated (${openBraces} open braces, ${closeBraces} close braces). Retry with another model.`);
        }

        try {
            const parsed = JSON.parse(jsonString);

            // Validate required fields exist
            if (!parsed.skills) {
                throw new Error("Invalid response format: missing 'skills' object");
            }

            // Validate we have at least some skill scores
            const skillCount = Object.keys(parsed.skills).length;
            if (skillCount === 0) {
                throw new Error("Invalid response format: 'skills' object is empty");
            }

            return parsed;

        } catch (e) {
            const errorDetail = e instanceof Error ? e.message : 'Unknown parse error';
            console.error("Failed to parse AI JSON response:", errorDetail);
            console.error("Raw response (first 500 chars):", raw.substring(0, 500));

            // Throw error to trigger model fallback in AI client
            throw new Error(`Assessment parse failed: ${errorDetail}. The AI model may need to retry.`);
        }
    }
}

import { CognitiveSkill } from '@/types/assessment';
import { SessionHistory } from './progress-store';

export function generateMockProgress(count: number, userId: string = 'demo-user'): SessionHistory[] {
    const sessions: SessionHistory[] = [];
    const baseDate = new Date();
    baseDate.setDate(baseDate.getDate() - count);

    const skillStartingPoints: Record<CognitiveSkill, number> = {
        'problem-decomposition': 4,
        'pattern-recognition': 3,
        'algorithmic-thinking': 4,
        'complexity-analysis': 2,
        'communication-clarity': 5,
        'edge-case-awareness': 3,
        'optimization-mindset': 2,
        'debugging-approach': 4,
    };

    for (let i = 0; i < count; i++) {
        const timestamp = new Date(baseDate);
        timestamp.setDate(timestamp.getDate() + i);
        timestamp.setHours(10 + (i % 8), 15 * (i % 4));

        const skills: Record<CognitiveSkill, number> = {} as any; // initialized empty, filled below
        Object.entries(skillStartingPoints).forEach(([skill, base]) => {
            // Gradual improvement logic with some randomness
            const progress = (i / count) * 4; // up to +4 points over time
            const random = (Math.random() - 0.5) * 1.5; // variance
            skills[skill as CognitiveSkill] = Math.max(1, Math.min(10, Math.round(base + progress + random)));
        });

        // Weighted average approx
        const overallScore = Object.values(skills).reduce((a, b) => a + b, 0) / 8;

        sessions.push({
            sessionId: `mock-${i}`,
            userId,
            problemId: ['two-sum', 'valid-anagram', 'merge-sorted-array'][i % 3],
            problemDifficulty: ['easy', 'medium', 'hard'][i % 3] as any,
            timestamp,
            duration: 600 + (Math.random() * 600),
            skills: skills,
            overallScore: Math.round(overallScore * 10) / 10
        });
    }

    return sessions.reverse(); // Newest first
}

import { CognitiveSkill } from '@/types/assessment';
import { SKILL_DEFINITIONS } from './skill-registry';

export interface SessionHistory {
    sessionId: string;
    userId: string;
    problemId: string;
    problemDifficulty: 'easy' | 'medium' | 'hard';
    timestamp: Date;
    duration: number; // seconds
    skills: Record<CognitiveSkill, number>;
    overallScore: number; // weighted average
    transcript?: { role: string; content: string }[]; // conversation history
}

export interface SkillTrend {
    skill: CognitiveSkill;
    trend: 'improving' | 'stable' | 'declining';
    recentScores: number[];
    change: number;
}

export interface UserProgressOverview {
    userId: string;
    totalSessions: number;
    averageScores: Record<CognitiveSkill, number>;
    trends: SkillTrend[];
    lastUpdated: Date;
}

export class ProgressStore {
    private readonly MAX_SESSIONS = 50;
    private readonly STORAGE_KEY_PREFIX = 'algomind_progress_';

    async saveSession(session: SessionHistory): Promise<void> {
        const key = `${this.STORAGE_KEY_PREFIX}${session.userId}`;

        try {
            const existingData = this.getRawProgress(session.userId);
            const updatedSessions = [session, ...existingData].sort(
                (a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()
            );

            const pruned = this.pruneOldSessions(updatedSessions);
            localStorage.setItem(key, JSON.stringify(pruned));
        } catch (error: unknown) {
            if ((error as any).name === 'QuotaExceededError') {
                console.warn("Storage quota exceeded. Forcing prune and retrying.");
                this.forceClearOldest(session.userId);
                return this.saveSession(session);
            }
            throw error;
        }
    }

    async getUserHistory(userId: string): Promise<SessionHistory[]> {
        return this.getRawProgress(userId).map(s => ({
            ...s,
            timestamp: new Date(s.timestamp)
        }));
    }

    private getRawProgress(userId: string): SessionHistory[] {
        const key = `${this.STORAGE_KEY_PREFIX}${userId}`;
        const data = localStorage.getItem(key);
        if (!data) return [];
        try {
            return JSON.parse(data);
        } catch {
            return [];
        }
    }

    private pruneOldSessions(sessions: SessionHistory[]): SessionHistory[] {
        if (sessions.length <= this.MAX_SESSIONS) return sessions;
        return sessions.slice(0, this.MAX_SESSIONS);
    }

    private forceClearOldest(userId: string): void {
        const sessions = this.getRawProgress(userId);
        if (sessions.length > 10) {
            const pruned = sessions.slice(0, Math.floor(sessions.length / 2));
            localStorage.setItem(`${this.STORAGE_KEY_PREFIX}${userId}`, JSON.stringify(pruned));
        } else {
            localStorage.removeItem(`${this.STORAGE_KEY_PREFIX}${userId}`);
        }
    }

    getStorageSize(userId: string): number {
        const data = localStorage.getItem(`${this.STORAGE_KEY_PREFIX}${userId}`);
        return data ? new Blob([data]).size : 0;
    }

    calculateWeightedScore(skills: Record<CognitiveSkill, number>): number {
        let totalScore = 0;
        let totalWeight = 0;

        Object.entries(skills).forEach(([skillId, score]) => {
            const weight = SKILL_DEFINITIONS[skillId as CognitiveSkill]?.weight || 0;
            totalScore += score * weight;
            totalWeight += weight;
        });

        return totalWeight === 0 ? 0 : Math.round((totalScore / totalWeight) * 10) / 10;
    }
}

