import { CognitiveSkill } from '@/types/assessment';

export interface TrendAnalysis {
    trend: 'improving' | 'stable' | 'declining';
    change: number; // percentage change
    confidence: number;
}

/**
 * Calculates a trend based on a series of scores using simple linear regression (slope)
 */
export function calculateTrend(scores: number[]): TrendAnalysis {
    if (scores.length < 2) {
        return { trend: 'stable', change: 0, confidence: 0 };
    }

    const n = scores.length;
    let sumX = 0;
    let sumY = 0;
    let sumXY = 0;
    let sumX2 = 0;

    for (let i = 0; i < n; i++) {
        sumX += i;
        sumY += scores[i];
        sumXY += i * scores[i];
        sumX2 += i * i;
    }

    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);

    // Calculate percentage change between first and last (smoothed)
    const first = scores[0];
    const last = scores[n - 1];
    const change = first === 0 ? 0 : ((last - first) / first) * 100;

    let trend: 'improving' | 'stable' | 'declining' = 'stable';
    if (slope > 0.15) trend = 'improving';
    else if (slope < -0.15) trend = 'declining';

    return {
        trend,
        change: Math.round(change),
        confidence: Math.min(n / 10, 1.0) // higher confidence with more data points
    };
}

'use client';

import { useEffect } from 'react';
import { getSupabase } from '@/lib/supabase/client';

/**
 * Manages session persistence and refresh
 * Helps prevent unexpected logouts
 */
export function useSessionPersistence() {
    useEffect(() => {
        const supabase = getSupabase();
        if (!supabase) return;

        // Listen for auth state changes
        const { data: { subscription } } = supabase.auth.onAuthStateChange(
            async (event: string, session: unknown) => {
                console.log('🔐 [SESSION] Auth event:', event);

                if (event === 'SIGNED_OUT') {
                    console.log('🔐 [SESSION] User signed out - clearing local data');
                    // Clear any cached data
                    localStorage.removeItem('attempted_problems');
                    sessionStorage.clear();
                }

                if (event === 'TOKEN_REFRESHED') {
                    console.log('🔐 [SESSION] Token refreshed successfully');
                }

                if (event === 'SIGNED_IN') {
                    console.log('🔐 [SESSION] User signed in');
                }
            }
        );

        // Refresh session every 50 minutes (tokens expire after 60 min)
        const refreshInterval = setInterval(async () => {
            const { data: { session } } = await supabase.auth.getSession();

            if (session) {
                console.log('🔄 [SESSION] Refreshing token...');
                const { error } = await supabase.auth.refreshSession();

                if (error) {
                    console.error('❌ [SESSION] Refresh failed:', error);
                } else {
                    console.log('✅ [SESSION] Token refreshed');
                }
            }
        }, 50 * 60 * 1000); // 50 minutes

        return () => {
            subscription.unsubscribe();
            clearInterval(refreshInterval);
        };
    }, []);
}

export class APIError extends Error {
    constructor(
        message: string,
        public statusCode?: number,
        public retryable: boolean = false
    ) {
        super(message);
        this.name = 'APIError';
    }
}

export async function handleAPIError(error: unknown): Promise<never> {
    if (error instanceof APIError) {
        throw error;
    }

    if (error instanceof Error) {
        const message = error.message.toLowerCase();

        if (message.includes('rate') || message.includes('limit') || message.includes('quota')) {
            throw new APIError('Rate limit exceeded. Please try again in a moment.', 429, true);
        }

        if (message.includes('network') || message.includes('fetch')) {
            throw new APIError('Network error. Please check your connection.', 0, true);
        }

        if (message.includes('timeout')) {
            throw new APIError('Request timed out. Please try again.', 408, true);
        }

        if (message.includes('unauthorized') || message.includes('401')) {
            throw new APIError('Authentication failed. Please refresh the page.', 401, false);
        }
    }

    throw new APIError('An unexpected error occurred. Please try again.', 500, true);
}

export async function retryWithBackoff<T>(
    fn: () => Promise<T>,
    maxRetries: number = 3,
    baseDelayMs: number = 1000
): Promise<T> {
    let lastError: Error = new Error('No attempts made');

    for (let attempt = 0; attempt < maxRetries; attempt++) {
        try {
            return await fn();
        } catch (error: unknown) {
            lastError = error instanceof Error ? error : new Error(String(error));

            // Don't retry non-retryable errors
            if (error instanceof APIError && !error.retryable) {
                throw error;
            }

            if (attempt < maxRetries - 1) {
                // Exponential backoff with jitter
                const delay = Math.min(baseDelayMs * Math.pow(2, attempt), 10000);
                const jitter = Math.random() * 500;
                await new Promise(resolve => setTimeout(resolve, delay + jitter));
            }
        }
    }

    throw lastError;
}

/**
 * Wrap an async function with automatic error handling
 */
export function withErrorHandling<T extends (...args: any[]) => Promise<any>>(
    fn: T,
    onError?: (error: Error) => void
): T {
    return (async (...args: Parameters<T>) => {
        try {
            return await fn(...args);
        } catch (error: unknown) {
            const handledError = error instanceof Error ? error : new Error(String(error));
            onError?.(handledError);
            throw handledError;
        }
    }) as T;
}

/**
 * Check if an error is transient and should be retried
 */
export function isTransientError(error: unknown): boolean {
    if (error instanceof APIError) {
        return error.retryable;
    }

    if (error instanceof Error) {
        const message = error.message.toLowerCase();
        return (
            message.includes('network') ||
            message.includes('timeout') ||
            message.includes('rate') ||
            message.includes('503') ||
            message.includes('502') ||
            message.includes('504')
        );
    }

    return false;
}

