        description: 'Allow interviews in Hinglish (Hindi + English mix)',
        requiresBrowserSupport: false,
    },
} as const;

export type FeatureFlagKey = keyof typeof FEATURE_FLAGS;

/**
 * Get feature flag value from localStorage with fallback to default
 */
export function getFeatureFlag(flag: FeatureFlagKey): boolean {
    if (typeof window === 'undefined') {
        return FEATURE_FLAGS[flag].defaultValue;
    }

    const stored = localStorage.getItem(FEATURE_FLAGS[flag].storageKey);
    if (stored === null) {
        return FEATURE_FLAGS[flag].defaultValue;
    }

    return stored === 'true';
}

/**
 * Set feature flag value in localStorage
 */
export function setFeatureFlag(flag: FeatureFlagKey, value: boolean): void {
    if (typeof window === 'undefined') return;
    localStorage.setItem(FEATURE_FLAGS[flag].storageKey, value.toString());
    // Dispatch event for hook updates
    window.dispatchEvent(new StorageEvent('storage', {
        key: FEATURE_FLAGS[flag].storageKey, // Ensure this matches what we look for
        newValue: value.toString(),
        storageArea: localStorage,
    }));
}

/**
 * Check if browser supports a feature that requires browser APIs
 */
export function checkBrowserSupport(flag: FeatureFlagKey): boolean {
    if (!FEATURE_FLAGS[flag].requiresBrowserSupport) {
        return true;
    }

    // Check for VAD support (AudioContext + MediaStream)
    if (flag === 'ENABLE_VAD_INTERRUPTIONS') {
        return !!(
            typeof window !== 'undefined' &&
            (window.AudioContext || (window as any).webkitAudioContext) &&
            navigator.mediaDevices &&
            navigator.mediaDevices.getUserMedia
        );
    }

    return true;
}

// ─── A/B Assignment (sticky per device) ────────────────────────────
const AB_STORAGE_KEY = 'algomind_ab_group';

/** Returns a stable group (0-99) for the current device. */
export function getABGroup(): number {
    if (typeof window === 'undefined') return 0;
    const stored = localStorage.getItem(AB_STORAGE_KEY);
    if (stored !== null) return Number(stored);
    const group = Math.floor(Math.random() * 100);
    localStorage.setItem(AB_STORAGE_KEY, String(group));
    return group;
}

/** Check if the current device is in the "treatment" cohort (0-49 = true). */
export function isInTreatmentGroup(): boolean {
    return getABGroup() < 50;
}

/**
 * Reset a flag to its compiled default (remove override).
 */
export function resetFlag(flag: FeatureFlagKey): void {
    if (typeof window === 'undefined') return;
    localStorage.removeItem(FEATURE_FLAGS[flag].storageKey);
    // Dispatch event to update hooks
    window.dispatchEvent(new StorageEvent('storage', {
        key: FEATURE_FLAGS[flag].storageKey,
        newValue: null,
        storageArea: localStorage,
    }));
}

/**
 * Get all feature flags with their current values and support status
 */
export function getAllFeatureFlags() {
    return Object.entries(FEATURE_FLAGS).map(([key, config]) => ({
        key: key as FeatureFlagKey,
        ...config,
        currentValue: getFeatureFlag(key as FeatureFlagKey),
        browserSupported: checkBrowserSupport(key as FeatureFlagKey),
    }));
}

/**
 * Interruption context builder.
 *
 * When the user interrupts the AI mid-response, this utility builds a
 * concise prompt fragment that can be injected into the next AI turn so
 * the model is aware of what it was saying before being cut off.
 *
 * @module interruption-context
 */

/** Maximum characters of partial content to include in the prompt. */
const MAX_PARTIAL_LENGTH = 150;

/**
 * Build a context fragment describing an interrupted AI response.
 *
 * @param partialResponse - The text the AI had spoken before interruption.
 * @param interruptedAt   - Unix timestamp of the interruption.
 * @returns A short prompt fragment, or empty string if input is empty.
 */
export function buildInterruptionContext(
    partialResponse: string,
    interruptedAt: number,
): string {
    if (!partialResponse || partialResponse.trim().length === 0) {
        return '';
    }

    // Truncate to avoid bloating the prompt
    const truncated =
        partialResponse.length > MAX_PARTIAL_LENGTH
            ? partialResponse.slice(0, MAX_PARTIAL_LENGTH).trimEnd() + '…'
            : partialResponse;

    return (
        `[INTERRUPTION CONTEXT] You were explaining: "${truncated}" ` +
        `but the user interrupted you. Briefly acknowledge what you were saying ` +
        `and address their new input. Do not repeat your previous explanation in full.`
    );
}

/**
 * Extract the portion of an AI response that was actually spoken (heard)
 * before the user interrupted.
 *
 * Since TTS processes text in sentence-level chunks, we estimate the
 * spoken portion by counting how many chunks could have been spoken
 * given the elapsed time since speech started.
 *
 * @param fullResponse   - The full AI response text.
 * @param speechStartMs  - Unix timestamp when speech began.
 * @param interruptionMs - Unix timestamp when interruption occurred.
 * @param avgChunkMs     - Average time to speak one chunk (default 3000ms).
 * @returns The estimated partial content that was heard.
 */
export function estimateSpokenContent(
    fullResponse: string,
    speechStartMs: number,
    interruptionMs: number,
    avgChunkMs = 3000,
): string {
    if (!fullResponse) return '';

    const elapsed = Math.max(0, interruptionMs - speechStartMs);
    const estimatedChunks = Math.max(1, Math.ceil(elapsed / avgChunkMs));

    // Split into sentences (rough approximation)
    const sentences = fullResponse.match(/[^.!?]+[.!?]+/g) || [fullResponse];
    const spokenSentences = sentences.slice(0, estimatedChunks);

    return spokenSentences.join('').trim();
}

export type InterviewState =
    | 'idle'
    | 'problem-intro'      // AI introduces problem
    | 'user-thinking'      // User explains approach
    | 'ai-clarifying'      // AI asks questions
    | 'user-solving'       // User walks through solution
    | 'ai-feedback'        // AI provides hints/feedback
    | 'solution-review'    // Final discussion
    | 'assessment'         // AI generates cognitive report
    | 'completed';

export type InterviewEvent =
    | 'START'
    | 'USER_FINISHED_SPEAKING'
    | 'AI_FINISHED_SPEAKING'
    | 'MOVE_TO_SOLVING'
    | 'REQUEST_HINT'
    | 'SUBMIT_SOLUTION'
    | 'FINISH_INTERVIEW';

export class InterviewStateMachine {
    private state: InterviewState = 'idle';

    getState(): InterviewState {
        return this.state;
    }

    transition(event: InterviewEvent): InterviewState {
        const previous = this.state;

        switch (this.state) {
            case 'idle':
                if (event === 'START') this.state = 'problem-intro';
                break;

            case 'problem-intro':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'user-thinking';
                break;

            case 'user-thinking':
                if (event === 'USER_FINISHED_SPEAKING') this.state = 'ai-clarifying';
                if (event === 'MOVE_TO_SOLVING') this.state = 'user-solving';
                break;

            case 'ai-clarifying':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'user-thinking'; // Loop back for more discussion
                if (event === 'MOVE_TO_SOLVING') this.state = 'user-solving';
                break;

            case 'user-solving':
                if (event === 'USER_FINISHED_SPEAKING') this.state = 'ai-feedback';
                if (event === 'SUBMIT_SOLUTION') this.state = 'solution-review';
                break;

            case 'ai-feedback':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'user-solving'; // Back to solving
                break;

            case 'solution-review':
                if (event === 'FINISH_INTERVIEW') this.state = 'assessment';
                break;

            case 'assessment':
                if (event === 'AI_FINISHED_SPEAKING') this.state = 'completed';
                break;
        }

        return this.state;
    }

    reset() {
        this.state = 'idle';
    }
}

import { createServerSupabase } from '@/lib/supabase/server';
import { getAIClient } from '@/lib/ai/client';
import { SearchResult, KnowledgeChunk } from './types';

export async function supabaseHybridSearch(query: string, limit = 3): Promise<SearchResult[]> {
    const supabase = await createServerSupabase();
    const client = getAIClient();

    // Get embedding for query
    // We use the same embed method as the ingestion script/vector store
    // getAIClient().embed returns { embeddings: number[][], ... }
    let queryVector: number[] | null = null;

    try {
        const { embeddings } = await client.embed(query);
        if (embeddings && embeddings.length > 0) {
            queryVector = embeddings[0];
        }
    } catch (error) {
        console.error('❌ [SupabaseVectorStore] Embedding failed:', error);
        // If embedding fails, we can't do vector search. 
        // We could fallback to keyword search if we implemented it via Postgres full text search,
        // but for now we'll throw or return empty.
        return [];
    }

    if (!queryVector) {
        return [];
    }

    // Vector search via RPC
    const { data, error } = await supabase.rpc('match_knowledge_chunks', {
        query_embedding: queryVector,
        match_threshold: 0.5, // Lowered threshold slightly to ensure recall
        match_count: limit
    });

    if (error) {
        console.error('❌ [SupabaseVectorStore] RPC matching failed:', error);
        throw error;
    }

    if (!data) return [];

    // Map to SearchResult interface
    return data.map((row: any) => {
        // Construct a partial KnowledgeChunk with available data
        const chunk: KnowledgeChunk = {
            id: row.id,
            topic: row.topic || 'unknown',
            subtopic: row.subtopic || 'unknown',
            title: row.title || 'Untitled',
            content: row.content || '',
            // Fill required fields with defaults as they aren't returned by RPC currently
            keywords: [],
            difficulty: 'medium',
            patterns: []
        };

        return {
            chunk,
            score: row.similarity,
            matchType: 'semantic' as const
        };
    });
}

