    await page.screenshot({
        path: `test-results/debug-${label}-${Date.now()}.png`,
        fullPage: true
    });

    // Get all relevant state
    const mainStatus = await page.getByTestId('interview-status-main').textContent().catch(() => 'NOT FOUND');
