    const micDisabled = await page.getByTestId('mic-button').first().isDisabled().catch(() => true);

    console.log(`[DEBUG ${label}] Main Status: ${mainStatus}`);
    console.log(`[DEBUG ${label}] Mic Status: ${micStatus}`);
